+    case "code": {
+      const code = node as Code;
+      const className = code.lang ? ` class="language-${escapeAttr(code.lang)}"` : "";
+      return withSource("pre", code, `<code${className}>${escapeHtml(code.value)}</code>`, "", false, sourceMap, resolveLineAtOffset);
